	-- ["51 {item:10940} for {spell:7420}: {skill:333}: disenchant green items of item level 5-20."] = "51 {item:10940} für {spell:7420}: {skill:333}: grüne Gegenstände der Gegenstandsstufe 5-20 entzaubern.",
	-- ["71 {item:11083} for {item:11130}, {spell:13501} and {spell:13637}: {skill:333}: disenchant green items of item level 21-30."] = "71 {item:11083} für {item:11130}, {spell:13501} und {spell:13637}: {skill:333}: grüne Gegenstände der Gegenstandsstufe 21-30 entzaubern.",
	-- ["Apprentice {skill:333}"] = "{skill:333} (Lehrling)",
	-- ["Apprentice {skill:333} lets you craft up to 75 for 10c, at any character level. Not every {skill:333} trainer teaches it: Alliance {npc:3606} ({zone:1438}), {npc:11068} ({zone:1453}), {npc:257004} (Zephras Isle), {npc:11070} ({zone:1457}), {npc:257020} (Zephras Isle) and {npc:11065} ({zone:1455}); Horde {npc:257004} (Zephras Isle), Jhag ({zone:1454}), {npc:11067} ({zone:1458}), {npc:11071} ({zone:1456}), {npc:257020} (Zephras Isle), {npc:266881} ({zone:1411}) and {npc:5695} ({zone:1420}). The arrow picks the nearest of your faction. Buy a {item:6217} and {item:247786} from an enchanting supplies vendor (in the capitals and on Zephras Isle; the starting-area trainers have none beside them, and the next step's arrow picks the nearest). From now on, disenchant every green you do not wear: that is where the dust and essences come from. Two starter quests teach Disenchant on a quest item: An Enchanting Lesson from {npc:11072} ({area:91}, {zone:1429}) and A Pain in the Neck from {npc:266881} ({area:367}, {zone:1411}). 1-75 takes about 50c of recipes and 4s 44c of vendor goods, plus 51 {item:10940} to gather or buy."] = "Die Lehrlingsstufe von {skill:333} erlaubt dir, bis 75 herzustellen, für 10c, auf jeder Charakterstufe. Nicht jeder {skill:333}-Lehrer bringt sie bei: Allianz {npc:3606} ({zone:1438}), {npc:11068} ({zone:1453}), {npc:257004} (Zephras Isle), {npc:11070} ({zone:1457}), {npc:257020} (Zephras Isle) und {npc:11065} ({zone:1455}); Horde {npc:257004} (Zephras Isle), Jhag ({zone:1454}), {npc:11067} ({zone:1458}), {npc:11071} ({zone:1456}), {npc:257020} (Zephras Isle), {npc:266881} ({zone:1411}) und {npc:5695} ({zone:1420}). Der Pfeil wählt den nächsten deiner Fraktion. Kauf eine {item:6217} und {item:247786} bei einem Händler für Verzauberbedarf (in den Hauptstädten und auf Zephras Isle; die Lehrer in den Startgebieten haben keinen in ihrer Nähe, und der Pfeil des nächsten Schritts wählt den nächsten). Ab jetzt entzauberst du jedes grüne Stück, das du nicht trägst: Daher kommen Staub und Essenzen. Zwei Startquests lehren Entzaubern an einem Questgegenstand: An Enchanting Lesson von {npc:11072} ({area:91}, {zone:1429}) und A Pain in the Neck von {npc:266881} ({area:367}, {zone:1411}). 1-75 kostet etwa 50c an Rezepten und 4s 44c an Händlerwaren, dazu 51 {item:10940} zum Sammeln oder Kaufen.",
	-- ["Apprentice {skill:333} lets you craft up to 75 for 10c, at any character level. Not every {skill:333} trainer teaches it: Alliance {npc:3606} ({zone:1438}), {npc:11068} ({zone:1453}), {npc:257004} (Zephras Isle), {npc:11070} ({zone:1457}), {npc:257020} (Zephras Isle) and {npc:11065} ({zone:1455}); Horde {npc:257004} (Zephras Isle), {npc:11066} ({zone:1454}), {npc:11067} ({zone:1458}), {npc:11071} ({zone:1456}), {npc:257020} (Zephras Isle), {npc:266881} ({zone:1411}) and {npc:5695} ({zone:1420}). The arrow picks the nearest of your faction. Buy a {item:6217} and {item:247786} from an enchanting supplies vendor (in the capitals and on Zephras Isle; the starting-area trainers have none beside them, and the next step's arrow picks the nearest). From now on, disenchant every green you do not wear: that is where the dust and essences come from. Two starter quests teach Disenchant on a quest item: An Enchanting Lesson from {npc:11072} ({area:91}, {zone:1429}) and A Pain in the Neck from {npc:266881} ({area:367}, {zone:1411}). 1-75 takes about 50c of recipes and 4s 44c of vendor goods, plus 51 {item:10940} to gather or buy."] = "Die Lehrlingsstufe von {skill:333} erlaubt dir, bis 75 herzustellen, für 10c, auf jeder Charakterstufe. Nicht jeder {skill:333}-Lehrer bringt sie bei: Allianz {npc:3606} ({zone:1438}), {npc:11068} ({zone:1453}), {npc:257004} (Die Insel Zephras), {npc:11070} ({zone:1457}), {npc:257020} (Die Insel Zephras) und {npc:11065} ({zone:1455}); Horde {npc:257004} (Die Insel Zephras), {npc:11066} ({zone:1454}), {npc:11067} ({zone:1458}), {npc:11071} ({zone:1456}), {npc:257020} (Die Insel Zephras), {npc:266881} ({zone:1411}) und {npc:5695} ({zone:1420}). Der Pfeil wählt den nächsten deiner Fraktion. Kauf eine {item:6217} und {item:247786} bei einem Verzauberbedarfshändler (in den Hauptstädten und auf Zephras Isle; bei den Lehrern in den Startgebieten gibt es keinen in der Nähe, und der Pfeil im nächsten Schritt wählt den nächsten). Entzaubere ab jetzt jeden grünen Gegenstand, den du nicht trägst: Daher stammen die Stäube und Essenzen. Zwei Startquests bringen dir Entzaubern an einem Questgegenstand bei: An Enchanting Lesson von {npc:11072} ({area:91}, {zone:1429}) und A Pain in the Neck von {npc:266881} ({area:367}, {zone:1411}). 1-75 kostet etwa 50c an Rezepten und 4s 44c an Händlerwaren, dazu 51 {item:10940} zum Sammeln oder Kaufen.",
	-- ["Apprentice {skill:333} lets you craft up to 75 for 10c, at any character level. Not every {skill:333} trainer teaches it: Alliance {npc:3606} ({zone:1438}), {npc:11068} ({zone:1453}), {npc:257004} (Zephras Isle), {npc:5157} ({zone:1455}), {npc:11072} ({zone:1429}), {npc:11070} ({zone:1457}), {npc:1317} ({zone:1453}), {npc:257020} (Zephras Isle), {npc:4213} ({zone:1457}), {npc:11065} ({zone:1455}), {npc:5158} ({zone:1455}) and {npc:7949} ({zone:1444}); Horde {npc:257004} (Zephras Isle), {npc:3345} ({zone:1454}), {npc:11074} ({zone:1442}), Jhag ({zone:1454}), {npc:4616} ({zone:1458}), {npc:11067} ({zone:1458}), {npc:11071} ({zone:1456}), {npc:257020} (Zephras Isle), {npc:3011} ({zone:1456}) and {npc:5695} ({zone:1420}). The arrow picks the nearest of your faction. Buy a {item:6217} and {item:247786} from an enchanting supplies vendor (in the capitals and on Zephras Isle; the starting-area trainers have none beside them, and the next step's arrow picks the nearest). From now on, disenchant every green you do not wear: that is where the dust and essences come from. Two starter quests teach Disenchant on a quest item: An Enchanting Lesson from {npc:11072} ({area:91}, {zone:1429}) and A Pain in the Neck from {npc:266881} ({area:367}, {zone:1411}). 1-75 takes about 50c of recipes and 4s 44c of vendor goods, plus 51 {item:10940} to gather or buy."] = "Die Lehrlingsstufe von {skill:333} erlaubt dir, bis 75 herzustellen, für 10c, auf jeder Charakterstufe. Nicht jeder {skill:333}-Lehrer bringt sie bei: Allianz {npc:3606} ({zone:1438}), {npc:11068} ({zone:1453}), {npc:257004} (Zephras Isle), {npc:5157} ({zone:1455}), {npc:11072} ({zone:1429}), {npc:11070} ({zone:1457}), {npc:1317} ({zone:1453}), {npc:257020} (Zephras Isle), {npc:4213} ({zone:1457}), {npc:11065} ({zone:1455}), {npc:5158} ({zone:1455}) und {npc:7949} ({zone:1444}); Horde {npc:257004} (Zephras Isle), {npc:3345} ({zone:1454}), {npc:11074} ({zone:1442}), Jhag ({zone:1454}), {npc:4616} ({zone:1458}), {npc:11067} ({zone:1458}), {npc:11071} ({zone:1456}), {npc:257020} (Zephras Isle), {npc:3011} ({zone:1456}) und {npc:5695} ({zone:1420}). Der Pfeil wählt den nächsten deiner Fraktion. Kauf eine {item:6217} und {item:247786} bei einem Verzauberbedarfshändler (in den Hauptstädten und auf Zephras Isle; bei den Lehrern in den Startgebieten gibt es keinen in der Nähe, und der Pfeil im nächsten Schritt wählt den nächsten). Entzaubere ab jetzt jeden grünen Gegenstand, den du nicht trägst: Daher stammen die Stäube und Essenzen. Zwei Startquests bringen dir Entzaubern an einem Questgegenstand bei: An Enchanting Lesson von {npc:11072} ({area:91}, {zone:1429}) und A Pain in the Neck von {npc:266881} ({area:367}, {zone:1411}). 1-75 kostet etwa 50c an Rezepten und 4s 44c an Händlerwaren, dazu 51 {item:10940} zum Sammeln oder Kaufen.",
	-- ["Artisan needs character level 35 and {skill:333} 200; it raises the cap to 300. Materials for 225-300 are worth about 30s in all."] = "Fachmann erfordert Charakterstufe 35 und {skill:333} 200; damit steigt die Obergrenze auf 300. Die Materialien für 225-300 sind insgesamt etwa 30s wert.",
	-- ["Artisan raises the cap from 225 to 300 for 5g (Classic's price; Forever's is not in the data); it needs {skill:333} 200 and character level 35, so you can take it on any visit from 200. {npc:11073} teaches Artisan {skill:333} inside the {area:1517} dungeon ({zone:1418}); bring a group. Learn now: {spell:13815} (from 210). 225-300 takes about 2g 20s of recipes and 1g 70s of vendor goods, plus 34 {item:8831}, 39 {item:11137} and 208 {item:11176} to gather or buy."] = "Die Meisterstufe erhöht das Limit von 225 auf 300 für 5g (Preis aus Classic; der von Forever liegt nicht in den Daten); sie erfordert {skill:333} 200 und Charakterstufe 35, du kannst sie also bei jedem Besuch ab 200 nehmen. {npc:11073} bringt die Meisterstufe von {skill:333} im Dungeon {area:1517} ({zone:1418}) bei; nimm eine Gruppe mit. Lerne jetzt: {spell:13815} (ab 210). 225-300 kostet etwa 2g 20s an Rezepten und 1g 70s an Händlerwaren, dazu 34 {item:8831}, 39 {item:11137} und 208 {item:11176} zum Sammeln oder Kaufen.",
	-- ["Artisan {skill:333}"] = "{skill:333} (Fachmann)",
	-- ["Back to an {skill:333} trainer: {spell:13501} is taught from {skill:333} 155."] = "Zurück zu einem Lehrer für {skill:333}: {spell:13501} wird ab {skill:333} 155 gelehrt.",
	-- ["Back to an {skill:333} trainer: {spell:13628}, {spell:13637} are taught from {skill:333} 180."] = "Zurück zu einem Lehrer für {skill:333}: {spell:13628}, {spell:13637} werden ab {skill:333} 180 gelehrt.",
	-- ["Back to an {skill:333} trainer: {spell:13661} is taught from {skill:333} 200."] = "Zurück zu einem Lehrer für {skill:333}: {spell:13661} wird ab {skill:333} 200 gelehrt.",
	-- ["Back to an {skill:333} trainer: {spell:13935} is taught from {skill:333} 255."] = "Zurück zu einem Lehrer für {skill:333}: {spell:13935} wird ab {skill:333} 255 gelehrt.",
	-- ["Back to an {skill:333} trainer: {spell:13948} is taught from {skill:333} 270."] = "Zurück zu einem Lehrer für {skill:333}: {spell:13948} wird ab {skill:333} 270 gelehrt.",
	-- ["Back to an {skill:333} trainer: {spell:7420} (from 15, 50c). Also learn {spell:1230643} (1s): Forever's {skill:333} camp item, 1 {item:4470} and 1 {item:10940}, placed at a campsite beside a campfire for its buff. The Camping 101: {skill:333} quest from your starting area's camping guide (after The Great Outdoors) sends you to an enchanting trainer who teaches it free."] = "Zurück zu einem {skill:333}-Lehrer: {spell:7420} (ab 15, 50c). Lerne außerdem {spell:1230643} (1s): Forevers {skill:333}-Lagergegenstand, 1 {item:4470} und 1 {item:10940}, der für seinen Buff an einem Lagerplatz neben einem Lagerfeuer aufgestellt wird. Die Quest Camping 101: {skill:333} aus dem Camping-Guide deines Startgebiets (nach The Great Outdoors) schickt dich zu einem Verzauberkunstlehrer, der sie dir kostenlos beibringt.",
	-- ["Back to an {skill:333} trainer: {spell:7426} is taught from {skill:333} 90."] = "Zurück zu einem Lehrer für {skill:333}: {spell:7426} wird ab {skill:333} 90 gelehrt.",
	-- ["Back to an {skill:333} trainer: {spell:7788} is taught from {skill:333} 120."] = "Zurück zu einem Lehrer für {skill:333}: {spell:7788} wird ab {skill:333} 120 gelehrt.",
	-- ["Back to an {skill:333} trainer: {spell:7795} (from 100) and {spell:13501} (from 130)."] = "Zurück zu einem {skill:333}-Lehrer: {spell:7795} (ab 100) und {spell:13501} (ab 130).",
	-- ["Back to an {skill:333} trainer: {spell:7795} is taught from {skill:333} 130."] = "Zurück zu einem Lehrer für {skill:333}: {spell:7795} wird ab {skill:333} 130 gelehrt.",
	-- ["Buy the whole bracket's share in one go: 1 {item:6217} (1s 24c) and 32 {item:247786} (3s 20c); about 4s 44c in all. The arrow picks the nearest seller of your faction ({zone:1453}: {npc:1286} and {npc:1318}; {zone:1454}: {npc:3367}, {npc:3346} and {npc:5817})."] = "Kauf den Bedarf für den ganzen Bereich auf einmal: 1 {item:6217} (1s 24c) und 32 {item:247786} (3s 20c); insgesamt etwa 4s 44c. Der Pfeil wählt den nächsten Händler deiner Fraktion ({zone:1453}: {npc:1286} und {npc:1318}; {zone:1454}: {npc:3367}, {npc:3346} und {npc:5817}).",
	-- ["Buy the whole bracket's share in one go: 34 {item:8925} (1g 70s); about 1g 70s in all. The arrow picks the nearest seller of your faction ({zone:1453}: {npc:1286}, Eldraeith and {npc:1325}; {zone:1454}: {npc:3367}, {npc:3348} and {npc:3334})."] = "Kauf den Bedarf für den ganzen Bereich auf einmal: 34 {item:8925} (1g 70s); insgesamt etwa 1g 70s. Der Pfeil wählt den nächsten Händler deiner Fraktion ({zone:1453}: {npc:1286}, Eldraeith und {npc:1325}; {zone:1454}: {npc:3367}, {npc:3348} und {npc:3334}).",
	-- ["Buy the whole bracket's share in one go: 4 {item:10938} (32s). The arrow picks the nearest seller of your faction. {item:10938}: no vendor of the other faction sells it; that side gathers or buys it at the Auction House (next steps)."] = "Kauf den Bedarf für den ganzen Bereich auf einmal: 4 {item:10938} (32s). Der Pfeil wählt den nächsten Händler deiner Fraktion. {item:10938}: Kein Händler der anderen Fraktion verkauft es; diese Seite sammelt es oder kauft es im Auktionshaus (nächste Schritte).",
	-- ["Expert needs character level 20 and {skill:333} 125; it raises the cap to 225. Materials for 150-225 are worth about 13s in all."] = "Experte erfordert Charakterstufe 20 und {skill:333} 125; damit steigt die Obergrenze auf 225. Die Materialien für 150-225 sind insgesamt etwa 13s wert.",
	-- ["Expert raises the cap from 150 to 225 for 50s (Classic's price; Forever's is not in the data); it needs {skill:333} 125 and character level 20, so you can take it on any visit from 125. Only a few trainers teach it: Alliance {npc:11072} ({zone:1429}); Horde {npc:11074} ({zone:1442}). The arrow picks the nearest of your faction. Learn now: {spell:13628} (from 150). 150-225 takes 1 {item:5500}, 1 {item:7971}, 1 {item:11082}, 71 {item:11083}, 1 {item:11128}, 1 {item:11135}, 21 {item:11137} and 1 {item:11144} to gather or buy. Come with all of it in your bags (the steps above, the rest from the Auction House): these trainers also teach {spell:13637} (from 160), {item:11145} (from 200) and {spell:13746} (from 205), and the crafts need no station, so craft right here and learn each recipe as you reach its skill. One trip instead of 3."] = "Die Expertenstufe erhöht das Limit von 150 auf 225 für 50s (Preis aus Classic; der von Forever liegt nicht in den Daten); sie erfordert {skill:333} 125 und Charakterstufe 20, du kannst sie also bei jedem Besuch ab 125 nehmen. Nur wenige Lehrer bringen sie bei: Allianz {npc:11072} ({zone:1429}); Horde {npc:11074} ({zone:1442}). Der Pfeil wählt den nächsten deiner Fraktion. Lerne jetzt: {spell:13628} (ab 150). 150-225 kostet 1 {item:5500}, 1 {item:7971}, 1 {item:11082}, 71 {item:11083}, 1 {item:11128}, 1 {item:11135}, 21 {item:11137} und 1 {item:11144} zum Sammeln oder Kaufen. Komm mit allem in deinen Taschen (die Schritte oben, den Rest aus dem Auktionshaus): Diese Lehrer bringen auch {spell:13637} (ab 160), {item:11145} (ab 200) und {spell:13746} (ab 205) bei, und die Herstellung braucht keine Station, also stell sie gleich hier her und lerne jedes Rezept, sobald du seine Fertigkeit erreichst. Ein Besuch statt 3.",
	-- ["Expert {skill:333}"] = "{skill:333} (Experte)",
	-- ["Journeyman needs character level 10 and {skill:333} 50; it raises the cap to 150. Materials for 75-150 are worth about 7g 51s in all."] = "Geselle erfordert Charakterstufe 10 und {skill:333} 50; damit steigt die Obergrenze auf 150. Die Materialien für 75-150 sind insgesamt etwa 7g 51s wert.",
	-- ["Journeyman raises the cap from 75 to 150 for 5s (Classic's price; Forever's is not in the data); it needs {skill:333} 50 and character level 10, so you can take it on any visit from 50. Not every {skill:333} trainer teaches it: Alliance {npc:5157} ({zone:1455}), {npc:11072} ({zone:1429}), {npc:1317} ({zone:1453}), {npc:4213} ({zone:1457}) and {npc:7949} ({zone:1444}); Horde {npc:3345} ({zone:1454}), {npc:11074} ({zone:1442}), {npc:4616} ({zone:1458}) and {npc:3011} ({zone:1456}). The arrow picks the nearest of your faction. Learn now: {spell:7771} (from 70, 2s). 75-150 takes about 2s of recipes, plus 1 {item:1210}, 1 {item:6338}, 4 {item:10938}, 121 {item:10940} and 20 {item:11083} to gather or buy."] = "Die Gesellenstufe erhöht das Limit von 75 auf 150 für 5s (Preis aus Classic; der von Forever liegt nicht in den Daten); sie erfordert {skill:333} 50 und Charakterstufe 10, du kannst sie also bei jedem Besuch ab 50 nehmen. Nicht jeder {skill:333}-Lehrer bringt sie bei: Allianz {npc:5157} ({zone:1455}), {npc:11072} ({zone:1429}), {npc:1317} ({zone:1453}), {npc:4213} ({zone:1457}) und {npc:7949} ({zone:1444}); Horde {npc:3345} ({zone:1454}), {npc:11074} ({zone:1442}), {npc:4616} ({zone:1458}) und {npc:3011} ({zone:1456}). Der Pfeil wählt den nächsten deiner Fraktion. Lerne jetzt: {spell:7771} (ab 70, 2s). 75-150 kostet etwa 2s an Rezepten, dazu 1 {item:1210}, 1 {item:6338}, 4 {item:10938}, 121 {item:10940} und 20 {item:11083} zum Sammeln oder Kaufen.",
	-- ["Journeyman raises the cap from 75 to 150 for 5s (Classic's price; Forever's is not in the data); it needs {skill:333} 50 and character level 10, so you can take it on any visit from 50. Not every {skill:333} trainer teaches it: Alliance {npc:5157} ({zone:1455}), {npc:1317} ({zone:1453}), {npc:4213} ({zone:1457}) and {npc:7949} ({zone:1444}); Horde {npc:3345} ({zone:1454}), {npc:4616} ({zone:1458}) and {npc:3011} ({zone:1456}). The arrow picks the nearest of your faction. Learn now: {spell:7771} (from 70, 2s). 75-150 takes about 2s of recipes, plus 1 {item:1210}, 1 {item:6338}, 4 {item:10938}, 121 {item:10940} and 20 {item:11083} to gather or buy."] = "Die Gesellenstufe erhöht das Limit von 75 auf 150 für 5s (Preis aus Classic; der von Forever liegt nicht in den Daten); sie erfordert {skill:333} 50 und Charakterstufe 10, du kannst sie also bei jedem Besuch ab 50 nehmen. Nicht jeder {skill:333}-Lehrer bringt sie bei: Allianz {npc:5157} ({zone:1455}), {npc:1317} ({zone:1453}), {npc:4213} ({zone:1457}) und {npc:7949} ({zone:1444}); Horde {npc:3345} ({zone:1454}), {npc:4616} ({zone:1458}) und {npc:3011} ({zone:1456}). Der Pfeil wählt den nächsten deiner Fraktion. Lerne jetzt: {spell:7771} (ab 70, 2s). 75-150 kostet etwa 2s an Rezepten, dazu 1 {item:1210}, 1 {item:6338}, 4 {item:10938}, 121 {item:10940} und 20 {item:11083} zum Sammeln oder Kaufen.",
	-- ["Journeyman {skill:333}"] = "{skill:333} (Geselle)",
	-- ["Open Giant Clams here. The Auction House works too."] = "Öffne hier Riesenmuscheln. Das Auktionshaus geht auch.",
	-- ["Orange (a point every craft) until 135, yellow until 155, green until 175. Enchant your own gear: any item for that slot will do. {skill:333} 150 is a Legacy System milestone."] = "Orange (jede Herstellung ein Punkt) bis 135, gelb bis 155, grün bis 175. Verzaubere deine eigene Ausrüstung: Jeder Gegenstand für diesen Platz genügt. {skill:333} 150 ist ein Meilenstein des Vermächtnissystems.",
	-- ["Orange (a point every craft) until 20, yellow until 22, green until 25. Enchant your own gear: any item for that slot will do."] = "Orange (jede Herstellung ein Punkt) bis 20, gelb bis 22, grün bis 25. Verzaubere deine eigene Ausrüstung: Jeder Gegenstand für diesen Platz genügt.",
	-- ["Orange (a point every craft) until 80, yellow until 100, green until 120. Enchant your own gear: any item for that slot will do."] = "Orange (jede Herstellung ein Punkt) bis 80, gelb bis 100, grün bis 120. Verzaubere deine eigene Ausrüstung: Jeder Gegenstand für diesen Platz genügt.",
	-- ["Orange (a point every craft) until 80, yellow until 100, green until 120. Enchant your own gear: any item for that slot will do. 75 is the Apprentice cap."] = "Orange (jede Herstellung ein Punkt) bis 80, gelb bis 100, grün bis 120. Verzaubere deine eigene Ausrüstung: Jeder Gegenstand für diesen Platz genügt. 75 ist die Obergrenze für Lehrling.",
	-- ["Skinned, disenchanted or crafted by another profession: gather them yourself or buy them on the Auction House."] = "Gehäutet, entzaubert oder von einem anderen Beruf hergestellt: Sammle sie selbst oder kauf sie im Auktionshaus.",
	-- ["Still at the Expert trainer: {spell:13637} (from 160)."] = "Noch beim Expertenlehrer: {spell:13637} (ab 160).",
	-- ["Still at the Expert trainer: {spell:13702} (from 200) and {spell:13746} (from 205)."] = "Noch beim Expertenlehrer: {spell:13702} (ab 200) und {spell:13746} (ab 205).",
